//! Amp + cab signal chain, shared by the pedal patch and the host renderer.
//!
//! ```text
//! in → input gain → NAM amp (one of the rig's captures) → cab (NAM / IR / none)
//!    → tilt EQ → output level → out
//! ```

use crate::a2::{A2, MAX_BLOCK};
use crate::fir::Fir;

/// One amp capture.
pub struct AmpSlot {
    pub name: &'static str,
    pub weights: &'static [f32],
    /// Linear gain after the amp (loudness normalisation + user trim).
    pub out_trim: f32,
}

/// Everything model-specific; generated by `rig-builder`.
pub struct RigData {
    pub name: &'static str,
    pub input_trim: f32,
    pub amps: &'static [AmpSlot],
    /// Cab NAM weights or IR taps (empty for no cab).
    pub cab: &'static [f32],
    pub cab_trim: f32,
}

/// The cab stage: a NAM model, an IR, or nothing.
pub trait CabStage {
    const NEW: Self;
    fn load(&mut self, data: &'static [f32]);
    fn process(&mut self, buf: &mut [f32]);
}

pub struct NoCab;

impl CabStage for NoCab {
    const NEW: Self = NoCab;
    fn load(&mut self, _: &'static [f32]) {}
    fn process(&mut self, _: &mut [f32]) {}
}

impl<const C: usize> CabStage for A2<C> {
    const NEW: Self = A2::NEW;
    fn load(&mut self, data: &'static [f32]) {
        A2::load(self, data)
    }
    fn process(&mut self, buf: &mut [f32]) {
        A2::process(self, buf)
    }
}

impl<const N: usize> CabStage for Fir<N> {
    const NEW: Self = Fir::NEW;
    fn load(&mut self, data: &'static [f32]) {
        Fir::load(self, data)
    }
    fn process(&mut self, buf: &mut [f32]) {
        Fir::process(self, buf)
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Param {
    /// Left knob: input drive, -18..+18 dB (0.5 = 0 dB).
    Gain = 0,
    /// Mid knob: tilt EQ around 700 Hz, ±6 dB (0.5 = flat).
    Tone = 1,
    /// Right knob: output level, -36..+12 dB (0.75 = 0 dB).
    Level = 2,
}

impl Param {
    pub const COUNT: usize = 3;

    pub fn from_index(i: usize) -> Option<Param> {
        match i {
            0 => Some(Param::Gain),
            1 => Some(Param::Tone),
            2 => Some(Param::Level),
            _ => None,
        }
    }

    pub fn default_value(self) -> f32 {
        match self {
            Param::Level => 0.75,
            _ => 0.5,
        }
    }
}

const SAMPLE_RATE: f32 = 48000.0;
const FADE_SAMPLES: u32 = 480; // 10 ms fade-in after switching amps
const SMOOTH: f32 = 0.002; // ~10 ms parameter smoothing
const TONE_HZ: f32 = 700.0;

/// The chain. `AC` = amp channel count (3 = A2-Lite), `Cab` = cab stage.
/// [`Rig::NEW`] is all zeros so a `static` lands in `.bss`; call [`Rig::init`].
pub struct Rig<const AC: usize, Cab: CabStage> {
    data: Option<&'static RigData>,
    amp: A2<AC>,
    cab: Cab,
    amp_index: usize,
    pending_amp: Option<usize>,
    fade: u32,
    cab_on: bool,
    in_gain: f32,
    in_gain_target: f32,
    out_gain: f32,
    out_gain_target: f32,
    tilt_on: bool,
    tilt_lo: f32,
    tilt_hi: f32,
    tone_a: f32,
    tone_lp: f32,
}

impl<const AC: usize, Cab: CabStage> Rig<AC, Cab> {
    pub const NEW: Self = Self {
        data: None,
        amp: A2::NEW,
        cab: Cab::NEW,
        amp_index: 0,
        pending_amp: None,
        fade: 0,
        cab_on: false,
        in_gain: 0.0,
        in_gain_target: 0.0,
        out_gain: 0.0,
        out_gain_target: 0.0,
        tilt_on: false,
        tilt_lo: 0.0,
        tilt_hi: 0.0,
        tone_a: 0.0,
        tone_lp: 0.0,
    };

    pub fn init(&mut self, data: &'static RigData) {
        self.data = Some(data);
        for i in 0..Param::COUNT {
            let p = Param::from_index(i).unwrap();
            self.set_param(p, p.default_value());
        }
        self.in_gain = self.in_gain_target;
        self.out_gain = self.out_gain_target;
        self.pending_amp = None;
        self.fade = FADE_SAMPLES;
        self.cab_on = true;
        self.tone_lp = 0.0;
        self.tone_a = 1.0 - libm::expf(-2.0 * core::f32::consts::PI * TONE_HZ / SAMPLE_RATE);
        self.select_amp(0);
        self.cab.load(data.cab);
    }

    /// `value` in 0..=1.
    pub fn set_param(&mut self, p: Param, value: f32) {
        let v = value.clamp(0.0, 1.0);
        match p {
            Param::Gain => self.in_gain_target = db_to_lin((v - 0.5) * 36.0),
            Param::Tone => {
                let tilt = (v - 0.5) * 2.0;
                self.tilt_on = !(-0.001..=0.001).contains(&tilt);
                self.tilt_hi = db_to_lin(tilt * 6.0);
                self.tilt_lo = 1.0 / self.tilt_hi;
            }
            Param::Level => self.out_gain_target = db_to_lin((v - 0.75) * 48.0),
        }
    }

    /// Jump smoothed gains to their targets (for offline rendering).
    pub fn snap_params(&mut self) {
        self.in_gain = self.in_gain_target;
        self.out_gain = self.out_gain_target;
    }

    pub fn num_amps(&self) -> usize {
        self.data.map_or(0, |d| d.amps.len())
    }

    /// Footswitch: move to the next capture (fades, switch happens in process()).
    pub fn next_amp(&mut self) {
        let n = self.num_amps();
        if n > 1 {
            self.pending_amp = Some((self.amp_index + 1) % n);
        }
    }

    /// Immediate switch without fades (setup, not while playing).
    pub fn select_amp(&mut self, i: usize) {
        if let Some(d) = self.data {
            if !d.amps.is_empty() {
                self.amp_index = i % d.amps.len();
                self.amp.load(d.amps[self.amp_index].weights);
            }
        }
    }

    pub fn toggle_cab(&mut self) {
        self.cab_on = !self.cab_on;
    }

    pub fn amp_index(&self) -> usize {
        self.amp_index
    }

    pub fn amp_name(&self) -> &'static str {
        self.data.map_or("", |d| d.amps.get(self.amp_index).map_or("", |a| a.name))
    }

    pub fn cab_on(&self) -> bool {
        self.cab_on
    }

    /// Mono, in place, any length.
    pub fn process(&mut self, buf: &mut [f32]) {
        let Some(data) = self.data else {
            buf.fill(0.0);
            return;
        };
        for chunk in buf.chunks_mut(MAX_BLOCK) {
            self.process_chunk(data, chunk);
        }
    }

    fn process_chunk(&mut self, data: &'static RigData, buf: &mut [f32]) {
        let n = buf.len();
        for s in buf.iter_mut() {
            self.in_gain += (self.in_gain_target - self.in_gain) * SMOOTH;
            *s *= self.in_gain * data.input_trim;
        }

        self.amp.process(buf);
        let amp_trim = data.amps[self.amp_index].out_trim;
        for s in buf.iter_mut() {
            *s *= amp_trim;
        }

        if self.cab_on && !data.cab.is_empty() {
            self.cab.process(buf);
            for s in buf.iter_mut() {
                *s *= data.cab_trim;
            }
        }

        // Tilt EQ: one-pole split; the low-pass state runs even when flat so
        // turning the knob doesn't click.
        let a = self.tone_a;
        if self.tilt_on {
            for s in buf.iter_mut() {
                self.tone_lp += (*s - self.tone_lp) * a;
                *s = self.tone_lp * self.tilt_lo + (*s - self.tone_lp) * self.tilt_hi;
            }
        } else {
            for s in buf.iter() {
                self.tone_lp += (*s - self.tone_lp) * a;
            }
        }

        let switching = self.pending_amp.is_some();
        for (f, s) in buf.iter_mut().enumerate() {
            self.out_gain += (self.out_gain_target - self.out_gain) * SMOOTH;
            let mut g = self.out_gain;
            if self.fade < FADE_SAMPLES {
                g *= self.fade as f32 / FADE_SAMPLES as f32;
                self.fade += 1;
            }
            if switching {
                g *= (n - 1 - f) as f32 / n as f32; // fade out over this chunk
            }
            // Safety clamp: the SDK wants output inside (-1, 1).
            *s = (*s * g).clamp(-0.999, 0.999);
        }

        if let Some(next) = self.pending_amp.take() {
            self.select_amp(next);
            self.fade = 0;
        }
    }
}

fn db_to_lin(db: f32) -> f32 {
    libm::powf(10.0, db / 20.0)
}
